<div class="page-heading"><div><div class="eyebrow">PLAYBOOK / EDICIÓN</div><h1><?=!empty($item)?'Editar':'Nueva'?> <em>ficha táctica</em></h1><p>Documenta un plan con contexto de mapa, bando y utilidad.</p></div><a class="btn" href="<?=e(url('tacticas'))?>">← Volver</a></div><section class="panel narrow"><form method="post" action="<?=e(url('tactica-guardar'))?>" class="form-stack"><?=csrfField()?><input type="hidden" name="id" value="<?=e($item['id_estrategia']??0)?>"><label>Título de la estrategia<input name="titulo" value="<?=e($item['titulo']??'')?>" maxlength="150" required></label><div class="form-grid"><label>Mapa<select name="id_mapa" required><option value="">Seleccionar mapa</option><?php foreach($maps as $m):?><option value="<?=e($m['id_mapa'])?>" <?=($item['id_mapa']??null)==$m['id_mapa']?'selected':''?>><?=e($m['nombre_mapa'])?><?=((int)$m['activo_competitivo']===1?' · Activo':' · Histórico')?></option><?php endforeach;?></select></label><label>Bando<select name="bando"><option value="Atacante" <?=($item['bando']??'')==='Atacante'?'selected':''?>>Atacante</option><option value="Defensor" <?=($item['bando']??'')==='Defensor'?'selected':''?>>Defensor</option></select></label></div><label>Agente clave<input name="agente_clave" maxlength="50" value="<?=e($item['agente_clave']??'')?>" placeholder="Ej. Omen" required></label><label>Descripción detallada<textarea name="descripcion" rows="8" required placeholder="Objetivo, posicionamiento, utilidad, ejecución..."><?=e($item['descripcion']??'')?></textarea></label><label>VOD (opcional, enlace HTTPS YouTube/Twitch)<input type="url" name="link_vod" maxlength="255" value="<?=e($item['link_vod']??'')?>" placeholder="https://www.youtube.com/watch?v=..."></label><button class="btn btn-primary">Guardar ficha →</button></form></section>
